#!/usr/bin/env python3
"""Comprueba contra https://openrouter.ai/api/v1/models los modelos del workflow.

Uso:
  modelos.py listar            -> valida TODOS los modelos y enseña candidatos
  modelos.py elegir ETIQUETA   -> imprime líneas CLAVE=VALOR para $GITHUB_ENV
  modelos.py leer              -> lee el Issue (env CUERPO, TITULO) hecho con el
                                  formulario y dice qué etiqueta toca por la
                                  "Dificultad" elegida (+ un título corto).
                                  Si es "Automática" imprime ETIQUETA=auto
  modelos.py triaje            -> un modelo barato lee env TEXTO y decide el nivel
                                  (fácil/normal/difícil). Imprime ETIQUETA, NIVEL,
                                  RAZON y COSTE_TRIAJE. Nunca falla: si algo va mal
                                  elige "normal".
  modelos.py respuesta FICHERO -> saca de la charla de Aider (modo pregunta) solo
                                  la respuesta, sin los avisos técnicos
  modelos.py limpiar           -> limpia el comentario (env COMENTARIO): quita saltos de
                                  línea raros, espacios y la firma "Generated by ..." que
                                  algunas herramientas añaden al final
  modelos.py parte             -> escribe el "parte" de 4 líneas (qué hizo, modelos, tokens,
                                  coste de esta vez y acumulado) + una marca oculta con el
                                  coste, que se lee desde env (ver parte())
  modelos.py suma A B ...      -> suma costes tipo "$0.0015" (ignora lo que no sea cifra)
Los modelos vienen de variables de entorno definidas arriba en aider.yml.
"""
import json
import os
import re
import sys
import time
import unicodedata
import urllib.request

URL = "https://openrouter.ai/api/v1/models"


def catalogo():
    for intento in range(4):
        try:
            with urllib.request.urlopen(URL, timeout=30) as r:
                return {m["id"]: m for m in json.load(r)["data"]}
        except Exception as e:  # red caída, etc.
            print(f"(intento {intento + 1}) no pude leer OpenRouter: {e}", file=sys.stderr)
            time.sleep(2 ** intento)
    sys.exit("No se pudo consultar OpenRouter.")


def glm_mas_reciente(ids):
    """El z-ai/glm-X.Y más alto (sin variantes tipo -air, -flash, :free)."""
    cand = []
    for i in ids:
        m = re.fullmatch(r"z-ai/glm-(\d+(?:\.\d+)*)", i)
        if m:
            cand.append((tuple(int(x) for x in m.group(1).split(".")), i))
    return max(cand)[1] if cand else None


def plan(etiqueta, ids):
    """Devuelve (modo, piensa, escribe, barato) o None si no hay modelo."""
    e = os.environ
    if etiqueta == "aider":
        return ("simple", e["MODELO"], "", "")
    if etiqueta == "aider-pro":
        return ("arquitecto", e["MODELO_PRO_PIENSA"], e["MODELO"], e["MODELO"])
    if etiqueta in ("aider-max", "aider-reintento"):
        piensa = e["MODELO_MAX_KIMI"]
        if piensa not in ids:
            piensa = e["MODELO_MAX_GLM"]
        if piensa not in ids:
            piensa = glm_mas_reciente(ids) or piensa
        return ("arquitecto", piensa, e["MODELO"], e["MODELO"])
    return None


def sin_acentos(t):
    return "".join(c for c in unicodedata.normalize("NFD", t) if unicodedata.category(c) != "Mn").lower()


def secciones(cuerpo):
    """El formulario de GitHub guarda cada campo como '### Título' + texto."""
    res, actual = {}, None
    for linea in cuerpo.replace("\r", "").split("\n"):
        if linea.startswith("### "):
            actual = sin_acentos(linea[4:].strip())
            res[actual] = []
        elif actual is not None:
            res[actual].append(linea)
    return {k: "\n".join(v).strip() for k, v in res.items()}


DIFICULTAD = {"automatica": "auto", "facil": "aider", "normal": "aider-pro", "dificil": "aider-max"}


def _resumen(t):
    t = " ".join(t.split())
    return t[:70].rsplit(" ", 1)[0] + "…" if len(t) > 70 else t


def sin_palabra_agente(t):
    """'Agente, haz X' -> 'haz X' (con o sin coma, dos puntos, punto…)."""
    return re.sub(r"^\s*agente\b[\s,:;.\-]*", "", t or "", flags=re.I).strip()


def leer():
    sec = secciones(os.environ.get("CUERPO", ""))
    if "dificultad" not in sec:
        # Encargo libre que empieza por la palabra "Agente" (sin formulario): nivel automático.
        texto = sin_palabra_agente(os.environ.get("TITULO", "")) or sin_palabra_agente(os.environ.get("CUERPO", ""))
        texto = texto[:1].upper() + texto[1:]
        print("ETIQUETA=auto")
        print(f"RESUMEN={_resumen(texto)}")
        return
    valor = sin_acentos(sec.get("dificultad", "")).split(" ")[0]
    if valor not in DIFICULTAD:
        sys.exit(f"Dificultad no reconocida: {sec.get('dificultad')!r} (esperaba Automática, Fácil, Normal o Difícil)")
    print(f"ETIQUETA={DIFICULTAD[valor]}")
    print(f"RESUMEN={_resumen(sec.get('que quiero', ''))}")


NIVELES = {"facil": ("aider", "fácil"), "normal": ("aider-pro", "normal"), "dificil": ("aider-max", "difícil")}

PROMPT_TRIAJE = (
    "Eres el jefe de ingeniería de una app Android pequeña escrita en Kotlin. "
    "Te llega un encargo y debes decidir su nivel de dificultad para elegir qué modelo "
    "de IA lo programa (cuanto más difícil, más caro).\n"
    "- facil: cambio pequeño y localizado (un texto, un color, un tamaño, un botón, un aviso simple).\n"
    "- normal: cambio que toca varias partes o añade lógica nueva moderada.\n"
    "- dificil: cambio grande o delicado (varias pantallas, reestructurar, errores raros, "
    "riesgo de romper cosas, requisitos ambiguos).\n"
    "Ante la duda entre dos niveles, elige el más bajo. Responde SOLO con un JSON de una línea: "
    '{"nivel": "facil|normal|dificil", "razon": "una frase corta en español sencillo"}'
)


def una_linea(t, max_=250):
    t = " ".join(str(t).replace("`", "'").split())
    return t if len(t) <= max_ else t[: max_ - 1].rstrip() + "…"


def triaje():
    """Triaje con el modelo barato. Tope de coste: respuesta de como mucho 600 tokens."""
    modelo = os.environ["MODELO"]
    texto = os.environ.get("TEXTO", "")[:6000]
    nivel, razon, coste = "normal", "no pude hacer el triaje, uso el nivel normal por seguridad", 0.0
    tokens = "no disponible"
    try:
        clave = os.environ["OPENROUTER_API_KEY"]
        cuerpo = json.dumps({
            "model": modelo,
            "temperature": 0,
            "max_tokens": 600,
            "usage": {"include": True},
            "messages": [
                {"role": "system", "content": PROMPT_TRIAJE},
                {"role": "user", "content": "ENCARGO:\n" + texto},
            ],
        }).encode()
        req = urllib.request.Request(
            "https://openrouter.ai/api/v1/chat/completions", data=cuerpo,
            headers={"Authorization": "Bearer " + clave, "Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=60) as r:
            resp = json.load(r)
        contenido = resp["choices"][0]["message"].get("content") or ""
        print("(triaje) respuesta cruda:", contenido[:500], file=sys.stderr)
        uso = resp.get("usage", {})
        if uso.get("prompt_tokens") is not None and uso.get("completion_tokens") is not None:
            tokens = f"{uso['prompt_tokens']}/{uso['completion_tokens']}"
        if uso.get("cost") is not None:
            coste = float(uso["cost"])
        else:
            pr = catalogo().get(modelo, {}).get("pricing", {})
            coste = (uso.get("prompt_tokens", 0) * float(pr.get("prompt") or 0)
                     + uso.get("completion_tokens", 0) * float(pr.get("completion") or 0))
        m = re.search(r"\{.*\}", contenido, re.S)
        datos = json.loads(m.group(0))
        n = sin_acentos(str(datos.get("nivel", ""))).strip()
        if n in NIVELES:
            nivel, razon = n, una_linea(datos.get("razon", "")) or "sin motivo"
        else:
            razon = "el triaje no dio un nivel válido, uso el nivel normal por seguridad"
    except (Exception, SystemExit) as e:  # el triaje nunca debe parar el encargo
        print(f"(triaje) fallo: {e}", file=sys.stderr)
    etiqueta, bonito = NIVELES[nivel]
    print(f"ETIQUETA={etiqueta}")
    print(f"NIVEL={bonito}")
    print(f"RAZON={razon}")
    print(f"COSTE_TRIAJE=${coste:.6f}")
    print(f"TRIAJE_TOK={tokens}")


def respuesta(ruta):
    """Última respuesta del asistente en .aider.chat.history.md (sin líneas '> ' ni '#### ')."""
    lineas = open(ruta, encoding="utf-8", errors="replace").read().replace("\r", "").split("\n")
    ultimo = max((i for i, l in enumerate(lineas) if l.startswith("#### ")), default=-1)
    cola = [l for l in lineas[ultimo + 1:] if not l.startswith("> ")]
    print("\n".join(cola).strip()[:8000])


def limpiar():
    t = os.environ.get("COMENTARIO", "").replace("\r", "")
    t = re.sub(r"\n+\s*---\s*\n\s*_?Generated by .*$", "", t, flags=re.S)
    print(t.strip())


def _num(t):
    """'$0.0015' -> 0.0015 ; otra cosa -> None"""
    m = re.search(r"\d+(?:\.\d+)?", t or "")
    return float(m.group(0)) if m else None


def _tok(t):
    """'5.2k' -> 5200 ; '215' -> 215 ; otra cosa -> None"""
    t = t.strip().rstrip(".,").lower().replace(",", "")
    try:
        return float(t[:-1]) * 1000 if t.endswith("k") else float(t)
    except ValueError:
        return None


def _fmt_tok(n):
    return str(int(round(n))) if n < 1000 else f"{n / 1000:.1f}k"


MARCA = re.compile(r"<!--\s*coste:([0-9.]+)\s*-->")
LEGADO = re.compile(r"Coste aprox\.: \$([0-9.]+)")


def coste_previo(ruta):
    """Suma lo que ya costaron los comentarios del robot (Issue y sus PR).
    Cada comentario nuevo lleva una marca oculta <!-- coste:X -->; los antiguos,
    sin marca, se leen de su línea 'Coste aprox.: $X'."""
    total = 0.0
    try:
        comentarios = json.load(open(ruta, encoding="utf-8"))
    except Exception:
        return None
    for c in comentarios:
        if (c.get("user") or {}).get("login") != "github-actions[bot]":
            continue
        cuerpo = c.get("body") or ""
        marcas = MARCA.findall(cuerpo)
        if marcas:
            total += sum(float(x) for x in marcas)
        else:
            m = LEGADO.search(cuerpo)
            if m:
                total += float(m.group(1))
    return total


def _dinero(x):
    if x == 0:
        return "$0"
    return "<$0.0001" if x < 0.0001 else f"${x:.4f}"


def parte():
    """Parte de 4 líneas. Todo viene de datos reales; si falta algo, 'no disponible'.
    Entorno: FASE (inicio|fin), HECHO, MODO, PIENSA, ESCRIBE, TRIAJE_MODELO ('' si no hubo),
    TRIAJE_TOK, COSTE_TRIAJE, COSTE (de Aider), INCLUYE_TRIAJE (si|no: si la marca de
    este comentario debe incluir el triaje), LOG, COMENTARIOS, ISSUE.
    Revisión automática (opcional): REVISION_MODELO, REVISION_TOK, COSTE_REVISION y, si hubo
    arreglo, ARREGLO_MODELO, ARREGLO_LOG, COSTE_ARREGLO."""
    e = os.environ
    fase = e.get("FASE", "fin")
    modo = e.get("MODO", "simple")

    # --- línea 2: modelos
    tri_m = e.get("TRIAJE_MODELO", "")
    tri = f"triaje `{tri_m}`" if tri_m else "triaje no usado"
    if modo == "simple":
        fases = f"piensa y escribe `{e.get('PIENSA', 'no disponible')}`"
    else:
        fases = f"piensa `{e.get('PIENSA', 'no disponible')}` · escribe `{e.get('ESCRIBE', 'no disponible')}`"

    rev_m = e.get("REVISION_MODELO", "") if fase == "fin" else ""
    arr_m = e.get("ARREGLO_MODELO", "") if fase == "fin" else ""
    if rev_m:
        fases += f" · revisa `{rev_m}`"
    if arr_m:
        fases += f" · arregla `{arr_m}`"

    # --- línea 3: tokens (entrada/salida)
    tri_tok = f"triaje {e.get('TRIAJE_TOK', 'no disponible')}" if tri_m else "triaje no usado"
    if fase == "inicio":
        aider_tok = "Aider aún no ha empezado"
    else:
        try:
            lineas = re.findall(r"Tokens: (\S+) sent.*?(\S+) received", open(e.get("LOG", ""), encoding="utf-8", errors="replace").read())
        except OSError:
            lineas = []
        if not lineas:
            aider_tok = "Aider: no disponible"
        elif len(lineas) == 1:
            aider_tok = ("piensa y escribe " if modo == "simple" else "") + f"{lineas[0][0]}/{lineas[0][1]}"
        elif modo != "simple" and len(lineas) == 2:
            aider_tok = f"piensa {lineas[0][0]}/{lineas[0][1]} · escribe {lineas[1][0]}/{lineas[1][1]}"
        else:
            ent = [_tok(a) for a, _ in lineas]
            sal = [_tok(b) for _, b in lineas]
            if None in ent or None in sal:
                aider_tok = "Aider: no disponible"
            else:
                aider_tok = f"Aider en total ≈{_fmt_tok(sum(ent))}/{_fmt_tok(sum(sal))} (reparto por modelo: no disponible)"

    if rev_m:
        aider_tok += f" · revisión {e.get('REVISION_TOK') or 'no disponible'}"
    if arr_m:
        try:
            la = re.findall(r"Tokens: (\S+) sent.*?(\S+) received", open(e.get("ARREGLO_LOG", ""), encoding="utf-8", errors="replace").read())
        except OSError:
            la = []
        if len(la) == 1:
            aider_tok += f" · arreglo {la[0][0]}/{la[0][1]}"
        elif la and None not in [_tok(a) for a, _ in la] + [_tok(b) for _, b in la]:
            aider_tok += f" · arreglo ≈{_fmt_tok(sum(_tok(a) for a, _ in la))}/{_fmt_tok(sum(_tok(b) for _, b in la))}"
        else:
            aider_tok += " · arreglo no disponible"

    # --- línea 4: costes
    c_tri = _num(e.get("COSTE_TRIAJE", "")) or 0.0
    c_aider = None if fase == "inicio" else _num(e.get("COSTE", ""))
    if c_aider is not None:
        # revisión y arreglo se suman al coste de Aider (si no hay dato, cuentan 0 y se avisa abajo)
        c_aider += (_num(e.get("COSTE_REVISION", "")) or 0.0) if rev_m else 0.0
        c_aider += (_num(e.get("COSTE_ARREGLO", "")) or 0.0) if arr_m else 0.0
    esta_vez = c_tri + (c_aider or 0.0)
    if fase == "inicio":
        esta_txt = f"{_dinero(esta_vez)} (solo triaje, por ahora)"
    elif c_aider is None:
        esta_txt = f"Aider: no disponible (triaje {_dinero(c_tri)})"
    else:
        esta_txt = _dinero(esta_vez)
    marca = (c_tri if e.get("INCLUYE_TRIAJE", "si") == "si" else 0.0) + (c_aider or 0.0)
    previo = coste_previo(e["COMENTARIOS"]) if e.get("COMENTARIOS") else None
    if previo is None:
        acum_txt = "no disponible"
    else:
        acum = previo + marca
        acum_txt = _dinero(acum) + (" (como mínimo: faltan datos de Aider)" if (c_aider is None and fase == "fin") else "")

    print(f"📋 **Parte** · Hecho: {e.get('HECHO', 'no disponible')}")
    print(f"🧠 Modelos: {tri} · {fases}")
    print(f"🔢 Tokens (entrada/salida): {tri_tok} · {aider_tok}")
    print(f"💰 Coste: esta vez {esta_txt} · acumulado del Issue #{e.get('ISSUE', '?')}: {acum_txt}")
    print(f"<!-- coste:{marca:.6f} -->")


def suma(valores):
    total, alguno = 0.0, False
    for v in valores:
        m = re.search(r"\d+(?:\.\d+)?", v)
        if m:
            total += float(m.group(0))
            alguno = True
    print(f"${total:.4f}" if alguno else "no disponible")


def main():
    modo = sys.argv[1]
    if modo == "leer":
        return leer()
    if modo == "triaje":
        return triaje()
    if modo == "respuesta":
        return respuesta(sys.argv[2])
    if modo == "parte":
        return parte()
    if modo == "limpiar":
        return limpiar()
    if modo == "suma":
        return suma(sys.argv[2:])
    ids = catalogo()

    if modo == "listar":
        print("== Candidatos hoy en OpenRouter ==")
        for fam in ("deepseek/", "moonshotai/", "z-ai/"):
            print(f"-- {fam}")
            for i in sorted(x for x in ids if x.startswith(fam)):
                p = ids[i].get("pricing", {})
                print(f"   {i}  (entrada {p.get('prompt')}, salida {p.get('completion')} $/token)")
        print(f"GLM más reciente detectado: {glm_mas_reciente(ids)}")
        malos = []
        for et in ("aider", "aider-pro", "aider-max", "aider-reintento"):
            _, a, b, c = plan(et, ids)
            print(f"{et}: piensa={a} escribe={b or '-'} barato={c or '-'}")
            malos += [m for m in (a, b, c) if m and m not in ids]
        if malos:
            sys.exit(f"MODELOS QUE NO EXISTEN: {sorted(set(malos))}")
        print("OK: todos los modelos existen.")
        return

    etiqueta = sys.argv[2]
    p = plan(etiqueta, ids)
    if p is None:
        sys.exit(f"Etiqueta desconocida: {etiqueta}")
    modo_a, piensa, escribe, barato = p
    faltan = [m for m in (piensa, escribe, barato) if m and m not in ids]
    if faltan:
        with open("/tmp/modelos_error.txt", "w") as f:
            f.write(", ".join(sorted(set(faltan))))
        sys.exit(f"Modelos inexistentes en OpenRouter: {faltan}")
    for k, v in (("MODO", modo_a), ("PIENSA", piensa), ("ESCRIBE", escribe), ("BARATO", barato)):
        print(f"{k}={v}")


if __name__ == "__main__":
    main()
